     "image": "HuaweiCloudNationals(2324Answer)/Screenshot 2026-11-13 220128.png",
     "number": 35,
     "paperTotal": 90,
     "type": "single",
     "stem": "When John trains an image classification network and the hidden layer is a convolutional neural network, he finds that the network convergence speed is slow. The error in the training set is small, yet in the test set it is large. Which of the following options can he choose to alleviate the problem?",
     "options": [
      {
       "key": "A",
       "text": "Add Dropout to the hidden layer."
      },
      {
       "key": "B",
       "text": "Add the Batch Normalization layer after the convolution layer."
      },
      {
       "key": "C",
       "text": "Replace the convolutional layer with a fully connected layer."
      },
      {
       "key": "D",
       "text": "Increase the number of convolutional layers at the hidden layer."
      }
     ],
     "suppliedKey": "B",
     "suppliedExplanation": "The Batch Normalization layer can accelerate training, enhance model stability, and improve generalization. Option A: Dropout is a regularization technology that randomly discards some neurons during training to reduce model complexity and prevent overfitting. However, in some cases, if the convergence is slow, adding Dropout may further slow down the convergence speed because it reduces the capacity of models involved in training in each iteration. Option 8: Batch Normalization accelerates training and improves model stability by introducing a standardization layer between middle layers of the network. It not only helps alleviate the internal covariate offset, improve the training speed, but also improves the generalization capability of the model, thereby effectively relieving the overfitting problem. Option C: In an image processing task, a convolution layer is widely used because of its excellent spatial information processing capability. Replacing convolutional layer with fully connected layers is usually not a good choice because it may cause loss of spatial information, reduce the image processing capability of the model, and increase the risk of overfitting. Option D: Although increasing the complexity of the model may make the model perform better on the training set, this may also aggravate the overfitting problem and cause the performance deterioration on the test set. In addition, increasing the model complexity also increases the computing burden, which is contrary to the requirement of accelerating convergence.",
     "status": "transcribed",
     "issues": [],
